// Generate a random 32-bit unsigned input
uint32_t num = *FUZZ_PARAM(uint32_t);

// Invoke the target function
uint32_t res = next_pow_2(num);

// Validate documented invariant for small inputs: if num <= 1, the result must equal num
if (num <= 1u) {
    FUZZ_ASSERT(res == num, "next_pow_2(num<=1) must return num");
}

// For inputs where overflow cannot occur (num in [2, 2^31]), verify power-of-two and monotonicity properties
// Next power of two fits in 32 bits up to 2^31.
if (num > 1u && num <= 0x80000000u) {
    // res must be a power of two and >= num
    FUZZ_ASSERT(res != 0u, "next_pow_2 result should be non-zero in non-overflow range");
    FUZZ_ASSERT((res & (res - 1u)) == 0u, "next_pow_2 result should be a power of two");
    FUZZ_ASSERT(res >= num, "next_pow_2 result should be >= input");
}

